-- Reusable field icons belong to database authoring and its immutable publication.
-- Clients render semantic roles from that publication, never field-name heuristics.
ALTER TABLE public.taxonomy_attributes ADD COLUMN icon_name TEXT;
ALTER TABLE public.taxonomy_attributes ADD CONSTRAINT taxonomy_attribute_icon_name_check
  CHECK (icon_name IS NULL OR icon_name IN ('bath','battery','bed','book-open','briefcase','calendar','camera','car','check','clock','cpu','database','door','file','file-check','fuel','gauge','globe','heart','home','laptop','layers','layout-grid','leaf','map-pin','message','music','package','palette','paw','payment','plug','ruler','settings','shield','shield-alert','shirt','sofa','star','tag','thermometer','ticket','truck','user','users','wifi','wrench','zap'));

DO $functions$
DECLARE definition TEXT;
BEGIN
  SELECT pg_get_functiondef('public.read_taxonomy_draft()'::regprocedure) INTO definition;
  IF strpos(definition, '''code'', r.code, ''labels'', r.labels') = 0 THEN
    RAISE EXCEPTION 'Taxonomy field snapshot definition changed';
  END IF;
  EXECUTE replace(definition, '''code'', r.code, ''labels'', r.labels',
    '''code'', r.code, ''iconName'', r.icon_name, ''labels'', r.labels');
  SELECT pg_get_functiondef('public.update_taxonomy_draft(bigint,jsonb,uuid,text,text)'::regprocedure) INTO definition;
  IF strpos(definition, '''id'',''code'',''label'',''labels'',''data_type''') = 0 THEN
    RAISE EXCEPTION 'Taxonomy field command allowlist changed';
  END IF;
  EXECUTE replace(definition, '''id'',''code'',''label'',''labels'',''data_type''',
    '''id'',''code'',''label'',''labels'',''icon_name'',''data_type''');
END;
$functions$;

