yment","trial_lesson":"check","package_available":"payment","lesson_duration_minutes":"clock","target_age_group":"user","guardian_consent_required":"shield","maximum_students":"users","online_platform":"laptop","species":"paw","breed":"paw","animal_sex":"user","birth_date":"calendar","age_months":"calendar","animal_name":"user","identification_number":"tag","identification_type":"tag","pedigree_registry":"shield","pedigree":"shield","sterilized":"paw","vaccinated":"paw","health_certificate":"shield","transfer_type":"paw","breeder_status":"shield","bno_number":"shield","litter_count":"users","lost_found_date":"calendar","last_seen_location":"map-pin","distinctive_signs":"star","reward_offered":"payment","equipment_type":"briefcase","equipment_year":"calendar","usage_hours":"clock","power_source":"fuel","power_rating":"zap","serial_number_private":"tag","capacity_value":"layers","capacity_unit":"package","rental_available":"payment","daily_rental_price":"payment","weekly_rental_price":"payment","maintenance_status":"wrench","certification_status":"shield","delivery_installation":"truck","operator_training":"book-open","energy_efficiency_class":"leaf","phase_count":"layers","voltage":"zap","charging_connector":"plug","max_charging_power":"zap","storage_capacity_kwh":"battery","event_type":"ticket","event_name":"ticket","event_date":"calendar","event_end_date":"calendar","venue_name":"map-pin","seat_section":"ticket","seat_row":"ticket","seat_number":"ticket","ticket_type":"ticket","ticket_format":"ticket","organizer_name":"user","resale_reason":"ticket","storage_capacity_gb":"database","memory_ram_gb":"cpu","screen_size_in":"ruler","operating_system":"settings","network_lock_status":"wifi","battery_health_percent":"battery","imei_private":"tag","connectivity":"wifi","included_accessories":"package","console_platform":"laptop","game_genre":"layers","media_format":"layers","author_creator":"user","isbn_ean":"tag","publication_year":"calendar","instrument_type":"music","handedness":"user","appliance_type":"settings","appliance_capacity":"layers","furniture_type":"sofa","assembly_required":"wrench","safety_standard":"shield","manufacture_date":"calendar","delivery_origin":"truck","pickup_locality":"map-pin","pickup_postal_code":"map-pin","dropoff_locality":"map-pin","dropoff_postal_code":"map-pin","pickup_window_start":"clock","pickup_window_end":"clock","delivery_window_start":"clock","delivery_window_end":"clock","package_type":"package","package_count":"package","approximate_weight_kg":"ruler","package_dimensions":"ruler","handling_requirements":"package","required_vehicle_type":"car","loading_assistance_required":"users","delivery_budget":"payment","public_instructions":"file","pickup_address":"map-pin","dropoff_address":"map-pin","phone_reference_brand":"tag","phone_reference_family":"tag","phone_reference_model":"tag","phone_reference_variant":"tag","repair_history_status":"wrench","repair_history_details":"wrench"}$data$;
  configuration public.taxonomy_configuration;
  previous public.taxonomy_publications;
  document JSONB;
  next_revision BIGINT;
BEGIN
  UPDATE public.taxonomy_attributes a SET icon_name = entry.value, updated_at = now()
    FROM jsonb_each_text(authored) entry WHERE a.id = entry.key AND a.icon_name IS NULL;
  SELECT * INTO configuration FROM public.taxonomy_configuration WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  UPDATE public.taxonomy_configuration SET draft_revision = draft_revision + 1, updated_at = now() WHERE singleton;
  PERFORM public.refresh_taxonomy_draft_snapshot();
  SELECT * INTO previous FROM public.taxonomy_publications WHERE revision = configuration.published_revision;
  IF NOT FOUND THEN RETURN; END IF;
  -- Enrich only the previous public snapshot. Unpublished editorial changes stay in draft.
  document := jsonb_set(previous.snapshot, '{attributes}', (
    SELECT jsonb_agg(CASE WHEN authored ? (entry.value->>'id') AND NOT (entry.value ? 'iconName')
      THEN entry.value || jsonb_build_object('iconName', authored->(entry.value->>'id')) ELSE entry.value END ORDER BY entry.ordinality)
    FROM jsonb_array_elements(previous.snapshot->'attributes') WITH ORDINALITY entry(value, ordinality)
  ));
  INSERT INTO public.taxonomy_publications(taxonomy_version_id,draft_revision,checksum,snapshot,change_reason)
  VALUES(previous.taxonomy_version_id,configuration.draft_revision+1,
    encode(sha256(convert_to(document::text,'UTF8')),'hex'),document,'Publish authored semantic icons for listing characteristics')
  RETURNING revision INTO next_revision;
  UPDATE public.taxonomy_configuration SET published_revision=next_revision WHERE singleton;
  INSERT INTO public.taxonomy_migration_records(entity_type,identity,source_version,payload)
  VALUES('taxonomy_attribute_icons_v1',next_revision::text,'v1',
    jsonb_build_object('sourceRevision',previous.revision,'targetRevision',next_revision));
END;
$icons$;
